-- organization
-- A customer account; every user belongs to exactly one organization.
CREATE TABLE organization (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);

-- species
CREATE TABLE species (
    id INTEGER PRIMARY KEY,
    species TEXT
);

-- pets
-- my pets
CREATE TABLE pets (
    id INTEGER PRIMARY KEY,
    fk_id INTEGER REFERENCES organization(id),
    name TEXT,
    species INTEGER REFERENCES species(id)
);
CREATE INDEX pets_fk_id_idx ON pets (fk_id);

-- tags
CREATE TABLE tags (id INTEGER PRIMARY KEY, label TEXT NOT NULL);

-- users
-- People who can log in.
CREATE TABLE users (
  id INTEGER PRIMARY KEY,
  org_id INTEGER NOT NULL REFERENCES organization(id),
  email TEXT NOT NULL UNIQUE,
  manager_id INTEGER REFERENCES users(id)
);

-- projects
-- All my projects
CREATE TABLE projects (
  id INTEGER PRIMARY KEY,
  org_id INTEGER NOT NULL REFERENCES organization,
  owner_id INTEGER REFERENCES users(id),
  title TEXT NOT NULL
);

-- tasks
CREATE TABLE tasks (
  id INTEGER PRIMARY KEY,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  assignee_id INTEGER REFERENCES users(id),
  status TEXT NOT NULL DEFAULT 'open'
);

-- comments
CREATE TABLE comments (
  id INTEGER PRIMARY KEY,
  task_id INTEGER NOT NULL REFERENCES tasks(id),
  author_id INTEGER NOT NULL REFERENCES users(id),
  body TEXT
);

-- task_tags
-- Many-to-many link between tasks and tags
CREATE TABLE task_tags (
  task_id INTEGER REFERENCES tasks(id),
  tag_id INTEGER REFERENCES tags(id),
  PRIMARY KEY (task_id, tag_id)
);

